import { useEffect, useRef } from 'react'
import { CARD, LIVE } from './art'
import '../iso.css'
import './phone-city.css'

// The drawing is static and generated by figures/phone-city/build.mjs. This
// draws what moves: cars and people as small shaded boxes in the same camera,
// slotted into the painter's order each frame, and their marks on the phone's
// map. Cars and people on the phone's routes go into the glass, carry on as
// marks up the screen and round the map, and come back out.
const HTML = { __html: CARD }

const SVG_NS = 'http://www.w3.org/2000/svg'

// Speeds in metres (world units) per second.
const CAR_SPEED = 20
const RING_SPEED = 15
const WALK_SPEED = 3.2
const PORTAL_WALK_SPEED = 5

const CAR = { length: 11, width: 4.6 }
const PERSON = { size: 1.3, height: 2.6, head: 0.62 }

type Pt = [number, number]

const { cam } = LIVE
const iso = (x: number, y: number, z: number): Pt => [
  cam.ox + (x * cam.sinA - y * cam.cosA) * cam.k,
  cam.oy + ((x * cam.cosA + y * cam.sinA) * cam.sinE - z * cam.cosE) * cam.k,
]
const depthOf = (x: number, y: number, z: number) => (x * cam.cosA + y * cam.sinA) * cam.cosE + z * cam.sinE
const d1 = (n: number) => (Math.round(n * 10) / 10).toString()
const poly = (pts: Pt[]) => (pts.length ? 'M' + pts.map(([x, y]) => `${d1(x)} ${d1(y)}`).join('L') + 'Z' : '')

function hull(points: Pt[]): Pt[] {
  const p = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1])
  const cross = (o: Pt, a: Pt, b: Pt) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
  const lower: Pt[] = []
  for (const q of p) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], q) <= 0) lower.pop()
    lower.push(q)
  }
  const upper: Pt[] = []
  for (let i = p.length - 1; i >= 0; i--) {
    const q = p[i]
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], q) <= 0) upper.pop()
    upper.push(q)
  }
  return lower.slice(0, -1).concat(upper.slice(0, -1))
}

// A path walked by arc length.
class Route {
  pts: Pt[]
  cum: number[]
  length: number
  constructor(pts: number[][], closed: boolean) {
    this.pts = pts.map(([x, y]) => [x, y] as Pt)
    if (closed) this.pts.push(this.pts[0])
    this.cum = [0]
    for (let i = 1; i < this.pts.length; i++) {
      const [ax, ay] = this.pts[i - 1]
      const [bx, by] = this.pts[i]
      this.cum.push(this.cum[i - 1] + Math.hypot(bx - ax, by - ay))
    }
    this.length = this.cum[this.cum.length - 1]
  }
  at(s: number): Pt {
    const c = this.cum
    const t = Math.min(Math.max(s, 0), this.length)
    let lo = 0
    let hi = c.length - 1
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1
      if (c[mid] <= t) lo = mid
      else hi = mid
    }
    const f = (t - c[lo]) / (c[hi] - c[lo] || 1)
    const [ax, ay] = this.pts[lo]
    const [bx, by] = this.pts[hi]
    return [ax + (bx - ax) * f, ay + (by - ay) * f]
  }
}

// A path on the phone's screen: (u, v) in screen units with the drawing scale
// at each point, walked by world-equivalent length (screen length / scale), so
// marks keep the speed they had outside and slow as the road narrows.
class ScreenRoute {
  pts: number[][]
  cum: number[]
  length: number
  constructor(pts: number[][]) {
    this.pts = pts
    this.cum = [0]
    for (let i = 1; i < pts.length; i++) {
      const [au, av, ak] = pts[i - 1]
      const [bu, bv, bk] = pts[i]
      this.cum.push(this.cum[i - 1] + Math.hypot(bu - au, bv - av) / ((ak + bk) / 2))
    }
    this.length = this.cum[this.cum.length - 1]
  }
  at(w: number): [number, number, number] {
    const c = this.cum
    const t = Math.min(Math.max(w, 0), this.length)
    let lo = 0
    let hi = c.length - 1
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1
      if (c[mid] <= t) lo = mid
      else hi = mid
    }
    const f = (t - c[lo]) / (c[hi] - c[lo] || 1)
    const a = this.pts[lo]
    const b = this.pts[hi]
    return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f]
  }
  // The stretch between two lengths, as screen points.
  span(w0: number, w1: number): Pt[] {
    const out: Pt[] = []
    const [u0, v0] = this.at(w0)
    out.push([u0, v0])
    for (let i = 0; i < this.cum.length; i++) if (this.cum[i] > w0 && this.cum[i] < w1) out.push([this.pts[i][0], this.pts[i][1]])
    const [u1, v1] = this.at(w1)
    out.push([u1, v1])
    return out
  }
}

// A shaded box in the kit's style: paper fill, four side tones by facing,
// a lighter top, a crease and an outline.
type Box = { el: SVGGElement; fill: SVGPathElement; shades: SVGPathElement[]; top: SVGPathElement; crease: SVGPathElement; edge: SVGPathElement }

function makeBox(parent: SVGElement, tone: string, lit = false): Box {
  const el = document.createElementNS(SVG_NS, 'g')
  el.setAttribute('class', 'iso-solid')
  if (lit) el.setAttribute('data-lit', '')
  const path = (cls: string, extra: Record<string, string> = {}) => {
    const p = document.createElementNS(SVG_NS, 'path')
    p.setAttribute('class', cls)
    for (const [k, v] of Object.entries(extra)) p.setAttribute(k, v)
    el.appendChild(p)
    return p
  }
  const fill = path('iso-fill')
  const shades = [0, 1, 2, 3].map((s) => path('iso-shade', { 'data-shade': String(s) }))
  const top = path('iso-top')
  const crease = path('iso-line iso-crease', { 'data-tone': 'faint' })
  const edge = path('iso-line iso-edge', { 'data-tone': tone })
  parent.appendChild(el)
  return { el, fill, shades, top, crease, edge }
}

// Draws a box from a floor centre, a heading, half length and half width,
// and returns its screen points (for the mover's screen box).
function drawBox(b: Box, cx: number, cy: number, angle: number, hl: number, hw: number, z0: number, z1: number, out: Pt[], floor?: number[]) {
  const fx = Math.cos(angle)
  const fy = Math.sin(angle)
  const ring: Pt[] = [
    [cx - fx * hl + fy * hw, cy - fy * hl - fx * hw],
    [cx + fx * hl + fy * hw, cy + fy * hl - fx * hw],
    [cx + fx * hl - fy * hw, cy + fy * hl + fx * hw],
    [cx - fx * hl - fy * hw, cy - fy * hl + fx * hw],
  ]
  const top = ring.map(([x, y]) => iso(x, y, z1))
  const bottom = ring.map(([x, y]) => iso(x, y, z0))
  if (floor)
    for (const [x, y] of ring) {
      floor[0] = Math.min(floor[0], x)
      floor[1] = Math.min(floor[1], y)
      floor[2] = Math.max(floor[2], x)
      floor[3] = Math.max(floor[3], y)
    }
  const shades = ['', '', '', '']
  let crease = ''
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4
    const mx = (ring[i][0] + ring[j][0]) / 2 - cx
    const my = (ring[i][1] + ring[j][1]) / 2 - cy
    const len = Math.hypot(mx, my) || 1
    const nx = mx / len
    const ny = my / len
    if (nx * cam.cosA + ny * cam.sinA <= 1e-9) continue
    const lit = (nx * -cam.sinA + ny * cam.cosA + 1) / 2
    const shade = Math.min(3, Math.max(0, Math.floor(lit * 4)))
    shades[shade] += poly([top[i], top[j], bottom[j], bottom[i]])
    crease += `M${d1(top[i][0])} ${d1(top[i][1])}L${d1(top[j][0])} ${d1(top[j][1])}`
  }
  const outline = poly(hull([...top, ...bottom]))
  b.fill.setAttribute('d', outline)
  b.shades.forEach((p, i) => p.setAttribute('d', shades[i]))
  b.top.setAttribute('d', poly(top))
  b.crease.setAttribute('d', crease)
  b.edge.setAttribute('d', outline)
  b.el.style.display = ''
  out.push(...top, ...bottom)
}

const hideBox = (b: Box) => (b.el.style.display = 'none')

// Something that moves through the city and is slotted into the draw order.
type Mover = {
  el: SVGGElement
  box: [number, number, number, number, number, number]
  screen: [number, number, number, number]
  depth: number
  visible: boolean
  slot: number
}

export default function PhoneCity() {
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const root = ref.current
    if (!root) return
    const svg = root.querySelector('svg')!
    const layer = svg.querySelector<SVGGElement>('[data-items]')!
    const itemEls = [...layer.querySelectorAll<SVGGElement>(':scope > [data-i]')]
    const insideLayer = svg.querySelector<SVGGElement>('[data-inside]')!
    const mapDots = svg.querySelector<SVGGElement>('[data-mdots]')!
    const wins = [...svg.querySelectorAll<SVGPathElement>('.pc-win')]
    const still = matchMedia('(prefers-reduced-motion: reduce)')
    const created: Element[] = []

    const { road, block, items, map } = LIVE
    const toMap = (x: number, y: number): Pt => [map.x0 + (x - map.tileX) * map.scale, -map.top + (y - map.tileY) * map.scale]
    const onTile = (x: number, y: number) => x >= map.tileX && x <= map.tileX + 170 && y >= map.tileY && y <= map.tileY + 130

    const group = (parent: SVGElement, cls = '') => {
      const g = document.createElementNS(SVG_NS, 'g')
      if (cls) g.setAttribute('class', cls)
      parent.appendChild(g)
      created.push(g)
      return g
    }
    const shape = <K extends 'circle' | 'path'>(parent: SVGElement, tag: K, cls: string) => {
      const el = document.createElementNS(SVG_NS, tag)
      el.setAttribute('class', cls)
      parent.appendChild(el)
      created.push(el)
      return el
    }
    const newMover = (): Mover => ({ el: group(layer, 'pc-mover'), box: [0, 0, 0, 0, 0, 0], screen: [0, 0, 0, 0], depth: 0, visible: false, slot: -1 })

    // Sets a mover's world box, screen box and depth from what was drawn.
    function settle(m: Mover, pts: Pt[], lo: [number, number, number], hi: [number, number, number]) {
      m.visible = pts.length > 0
      if (!m.visible) return
      let sx0 = Infinity
      let sy0 = Infinity
      let sx1 = -Infinity
      let sy1 = -Infinity
      for (const [x, y] of pts) {
        if (x < sx0) sx0 = x
        if (y < sy0) sy0 = y
        if (x > sx1) sx1 = x
        if (y > sy1) sy1 = y
      }
      m.screen = [sx0, sy0, sx1, sy1]
      m.box = [...lo, ...hi]
      m.depth = depthOf((lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, lo[2])
    }

    // ---- cars: a chassis, a body and a cabin, laid along the car's axis from
    // its tail. `from`..`to` is the part that is outside the glass.
    type Car = { m: Mover; parts: Box[]; dot: SVGCircleElement }
    const makeCar = (lit: boolean): Car => {
      const m = newMover()
      return { m, parts: [makeBox(m.el, 'lo'), makeBox(m.el, lit ? 'lit' : 'mid', lit), makeBox(m.el, 'hi')], dot: shape(mapDots, 'circle', lit ? 'pc-mdot' : 'pc-mdot pc-mdot-dim') }
    }
    const CAR_PARTS: [number, number, number, number, number][] = [
      // from, to (along the car), half width, z0, z1 above the road
      [0.7, CAR.length - 0.7, CAR.width / 2 - 0.4, 0.1, 1.1],
      [0, CAR.length, CAR.width / 2, 1, 2.8],
      [CAR.length / 2 - 3.4, CAR.length / 2 + 2.2, CAR.width / 2 - 0.4, 2.8, 4.5],
    ]
    function drawCar(c: Car, tail: Pt, nose: Pt, from: number, to: number) {
      const ax = nose[0] - tail[0]
      const ay = nose[1] - tail[1]
      const len = Math.hypot(ax, ay) || 1
      const angle = Math.atan2(ay, ax)
      const ux = ax / len
      const uy = ay / len
      const pts: Pt[] = []
      const floor = [Infinity, Infinity, -Infinity, -Infinity]
      CAR_PARTS.forEach(([u0, u1, hw, z0, z1], i) => {
        const a = Math.max(u0, from)
        const b = Math.min(u1, to)
        if (b - a < 0.05) return hideBox(c.parts[i])
        const mid = (a + b) / 2
        drawBox(c.parts[i], tail[0] + ux * mid, tail[1] + uy * mid, angle, (b - a) / 2, hw, road + z0, road + z1, pts, floor)
      })
      settle(c.m, pts, [floor[0], floor[1], road], [floor[2], floor[3], road + 4.5])
      c.m.el.style.display = c.m.visible ? '' : 'none'
    }
    const hideCar = (c: Car) => {
      c.parts.forEach(hideBox)
      c.m.visible = false
      c.m.el.style.display = 'none'
    }

    // ---- people: a body box and a round head.
    type Person = { m: Mover; body: Box; head: SVGCircleElement }
    const makePerson = (lit: boolean): Person => {
      const m = newMover()
      const body = makeBox(m.el, lit ? 'lit' : 'hi', lit)
      const head = shape(m.el, 'circle', lit ? 'pc-head pc-head-lit' : 'pc-head')
      return { m, body, head }
    }
    function drawPerson(p: Person, x: number, y: number, angle: number, z: number, clipBehind = -Infinity) {
      const half = PERSON.size / 2
      // Clip the body at the glass (y = front) when walking through it.
      const y0 = Math.max(y - half, clipBehind)
      const y1 = y + half
      if (y1 - y0 < 0.05) return hidePerson(p)
      const pts: Pt[] = []
      const cy = (y0 + y1) / 2
      const clipped = y0 > y - half
      drawBox(p.body, x, cy, clipped ? Math.PI / 2 : angle, clipped ? (y1 - y0) / 2 : half, half, z, z + PERSON.height, pts)
      const headFits = y >= clipBehind
      const [hx, hy] = iso(x, y, z + PERSON.height + PERSON.head * 0.8)
      p.head.setAttribute('cx', d1(hx))
      p.head.setAttribute('cy', d1(hy))
      p.head.setAttribute('r', String(PERSON.head * cam.k))
      p.head.style.display = headFits ? '' : 'none'
      settle(p.m, pts, [x - half, y0, z], [x + half, y1, z + PERSON.height + PERSON.head * 2])
      p.m.el.style.display = ''
    }
    const hidePerson = (p: Person) => {
      p.m.visible = false
      p.m.el.style.display = 'none'
    }

    // ---- routes and who is on them
    const ring = new Route(LIVE.ring, true)
    const circuit = new Route(LIVE.circuit, false)
    const inside = new ScreenRoute(LIVE.inside)
    const circuitTotal = circuit.length + inside.length

    const ringCars = [0, 1, 2].map(() => makeCar(false))
    const portalCars = Array.from({ length: 6 }, () => ({ car: makeCar(true), mark: shape(insideLayer, 'path', 'pc-icar') }))
    const walks = LIVE.walks.flatMap((w) => {
      const route = new Route(w.path, true)
      return Array.from({ length: w.count }, (_, i) => ({ route, person: makePerson(false), offset: (i + 0.37) / w.count }))
    })
    const portalWalks = LIVE.portalWalks.flatMap((w, loop) => {
      const route = new Route(w.path3, false)
      const screen = new ScreenRoute(w.inside)
      return Array.from({ length: 4 }, (_, i) => ({
        route,
        screen,
        person: makePerson(true),
        mark: shape(insideLayer, 'circle', 'pc-iwalker'),
        offset: (i + loop * 0.5) / 4,
      }))
    })
    const movers: Mover[] = [...ringCars.map((c) => c.m), ...portalCars.map((p) => p.car.m), ...walks.map((w) => w.person.m), ...portalWalks.map((w) => w.person.m)]

    function frame(t: number) {
      // Cars round the inner ring.
      ringCars.forEach((c, i) => {
        const s = (t * RING_SPEED + (i / ringCars.length) * ring.length) % ring.length
        const nose = ring.at(s)
        const tail = ring.at(s - CAR.length < 0 ? s - CAR.length + ring.length : s - CAR.length)
        drawCar(c, tail, nose, 0, CAR.length)
        const [mx, my] = toMap(...ring.at(s - CAR.length / 2))
        c.dot.setAttribute('cx', d1(mx))
        c.dot.setAttribute('cy', d1(my))
        c.dot.setAttribute('r', '0.9')
      })

      // Cars on the phone's circuit: outside the glass along `circuit`, inside
      // along `inside`; a car crossing the glass is drawn on both sides of it.
      portalCars.forEach(({ car, mark }, i) => {
        const nose = (t * CAR_SPEED + (i / portalCars.length) * circuitTotal) % circuitTotal
        const tail = nose - CAR.length
        const L3 = circuit.length
        const a = Math.max(0, tail)
        const b = Math.min(L3, nose)
        if (b > a) {
          const pa = circuit.at(a)
          const pb = circuit.at(b)
          const dx = pb[0] - pa[0]
          const dy = pb[1] - pa[1]
          const len = Math.hypot(dx, dy) || 1
          const tailPt: Pt = [pa[0] - (dx / len) * (a - tail), pa[1] - (dy / len) * (a - tail)]
          const nosePt: Pt = [tailPt[0] + (dx / len) * CAR.length, tailPt[1] + (dy / len) * CAR.length]
          drawCar(car, tailPt, nosePt, a - tail, b - tail)
        } else hideCar(car)
        // The map dot while the car is on the city tile.
        const mid = Math.min(Math.max((a + b) / 2, 0), L3)
        const [x, y] = circuit.at(mid)
        if (b > a && onTile(x, y)) {
          const [mx, my] = toMap(x, y)
          car.dot.setAttribute('cx', d1(mx))
          car.dot.setAttribute('cy', d1(my))
          car.dot.setAttribute('r', '0.9')
          car.dot.style.display = ''
        } else car.dot.style.display = 'none'

        // Inside the phone: a capsule along the screen route.
        const spans: [number, number][] = []
        const i0 = Math.max(L3, tail)
        const i1 = Math.min(circuitTotal, nose)
        if (i1 > i0) spans.push([i0 - L3, i1 - L3])
        if (tail < 0) spans.push([inside.length + tail, inside.length])
        if (spans.length) {
          let d = ''
          let scale = 1
          for (const [w0, w1] of spans) {
            const pts = inside.span(w0, w1)
            d += 'M' + pts.map(([u, v]) => `${d1(u)} ${d1(v)}`).join('L')
            scale = inside.at((w0 + w1) / 2)[2]
          }
          mark.setAttribute('d', d)
          mark.style.strokeWidth = String(CAR.width * scale)
          mark.style.display = ''
        } else mark.style.display = 'none'
      })

      // Walkers round the blocks and the pond.
      walks.forEach(({ route, person, offset }) => {
        const s = (t * WALK_SPEED + offset * route.length) % route.length
        const [x, y] = route.at(s)
        const [x2, y2] = route.at(s + 0.5)
        drawPerson(person, x, y, Math.atan2(y2 - y, x2 - x), block)
      })

      // Walkers through the phone. `s` runs from the glass (just out) round
      // the plaza walk to the glass again, then on through the screen route.
      portalWalks.forEach(({ route, screen, person, mark, offset }) => {
        const L = route.length
        const total = L + screen.length
        const half = PERSON.size / 2
        const s = (t * PORTAL_WALK_SPEED + offset * total) % total
        const c = s > total - half ? s - total : s
        if (c >= -half && c <= L + half) {
          const start = route.at(0)
          const end = route.at(L)
          let x: number
          let y: number
          if (c < 0) [x, y] = [start[0], LIVE.front + c]
          else if (c > L) [x, y] = [end[0], LIVE.front - (c - L)]
          else [x, y] = route.at(c)
          const [x2, y2] = route.at(Math.min(Math.max(c, 0) + 0.5, L))
          const nearGlass = y - half < LIVE.front
          drawPerson(person, x, y, Math.atan2(y2 - y, x2 - x), road, nearGlass ? LIVE.front : -Infinity)
        } else hidePerson(person)
        const w = s - L
        if (w >= 0) {
          const [u, v, k] = screen.at(w)
          mark.setAttribute('cx', d1(u))
          mark.setAttribute('cy', d1(v))
          mark.setAttribute('r', String(Math.max(0.35, 0.9 * k)))
          mark.style.display = ''
        } else mark.style.display = 'none'
      })

      order()
    }

    // Slot every mover into the painter's order: after every item that is
    // behind it and before every item in front of it, where they overlap on
    // screen. Boxes that are apart on the floor decide by the axis that
    // separates them; a mover standing on an item's top is in front of it.
    function inFront(m: Mover, it: { b: number[]; s: number[] }) {
      const [sx0, sy0, sx1, sy1] = m.screen
      if (sx1 < it.s[0] || sx0 > it.s[2] || sy1 < it.s[1] || sy0 > it.s[3]) return 0
      const [x0, y0, z0, x1, y1, z1] = m.box
      const [ix0, iy0, iz0, ix1, iy1, iz1] = it.b
      const gaps: [number, number][] = [
        [x0 - ix1, 1],
        [ix0 - x1, -1],
        [y0 - iy1, 1],
        [iy0 - y1, -1],
        [z0 - iz1, 1],
        [iz0 - z1, -1],
      ]
      let best = -Infinity
      let side = 1
      for (const [gap, s] of gaps) {
        if (gap > best) {
          best = gap
          side = s
        }
      }
      return best > -0.05 ? side : 1
    }
    function order() {
      const n = items.length
      const groups = new Map<number, Mover[]>()
      for (const m of movers) {
        if (!m.visible) continue
        let after = -1
        let before = n
        for (let i = 0; i < n; i++) {
          const f = inFront(m, items[i])
          if (f > 0) after = i
          else if (f < 0 && i < before) before = i
        }
        const slot = after + 1 <= before ? after + 1 : before
        const list = groups.get(slot) ?? []
        list.push(m)
        groups.set(slot, list)
      }
      for (const [slot, list] of groups) {
        list.sort((a, b) => a.depth - b.depth)
        const anchor = slot < n ? itemEls[slot] : null
        let changed = false
        for (let i = 0; i < list.length; i++) {
          const want = i + 1 < list.length ? list[i + 1].el : anchor
          if (list[i].slot !== slot || list[i].el.nextSibling !== want) changed = true
        }
        if (!changed) continue
        for (const m of list) {
          layer.insertBefore(m.el, anchor)
          m.slot = slot
        }
      }
    }

    // Lit windows come and go one at a time.
    let winClock = 0
    wins.forEach((el, i) => el.toggleAttribute('data-on', (i * 7) % 3 !== 0))

    let raf = 0
    let previous = 0
    let time = 4
    let visible = false

    function tick(now: number) {
      const dt = previous ? Math.min((now - previous) / 1000, 1 / 20) : 1 / 60
      previous = now
      time += dt
      winClock += dt
      if (winClock > 1.4 && wins.length) {
        winClock = 0
        wins[Math.floor(Math.random() * wins.length)].toggleAttribute('data-on')
      }
      frame(time)
      raf = visible && !still.matches ? requestAnimationFrame(tick) : 0
    }
    function run() {
      if (!raf && visible && !still.matches) {
        previous = 0
        raf = requestAnimationFrame(tick)
      }
    }

    // Hovering a building lights it and its footprint on the phone's map.
    let hovering = -1
    const over = (event: PointerEvent) => {
      const b = event.target instanceof Element ? event.target.closest<SVGGElement>('.pc-bld') : null
      const index = b ? Number(b.dataset.b) : -1
      if (index === hovering) return
      hovering = index
      svg.querySelectorAll('[data-b]').forEach((el) => el.toggleAttribute('data-on', Number(el.getAttribute('data-b')) === index))
    }
    const out = () => {
      hovering = -1
      svg.querySelectorAll('[data-b]').forEach((el) => el.removeAttribute('data-on'))
    }
    svg.addEventListener('pointerover', over)
    svg.addEventListener('pointerleave', out)

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[entries.length - 1].isIntersecting
        if (visible) run()
      },
      { rootMargin: '120px 0px' },
    )
    io.observe(root)
    const onMotion = () => {
      frame(time)
      run()
    }
    still.addEventListener('change', onMotion)

    frame(time)

    return () => {
      cancelAnimationFrame(raf)
      io.disconnect()
      still.removeEventListener('change', onMotion)
      svg.removeEventListener('pointerover', over)
      svg.removeEventListener('pointerleave', out)
      created.forEach((el) => el.remove())
    }
  }, [])

  return <div ref={ref} className="iso pc" dangerouslySetInnerHTML={HTML} />
}
